<?php $u=require_user(); ?>
<section class="section"><p class="eyebrow">YOUR WIKI WORLD</p><h1>Hello, <?=e(explode(' ',$u['name'])[0])?>.</h1><div class="account-grid"><aside class="side-nav"><?php foreach(['dashboard'=>'Overview','orders'=>'My orders','profile'=>'My profile','addresses'=>'My addresses','wishlist'=>'Wishlist','returns'=>'Returns'] as $key=>$label): ?><a class="<?=$section===$key?'selected':''?>" href="/account/<?=e($key)?>"><?=e($label)?> ↗</a><?php endforeach ?><form method="post" action="/account"><?=csrf_field()?><input type="hidden" name="action" value="logout"><button class="text-button">Sign out</button></form></aside><div>
<?php if($section==='dashboard'): ?><h2>A little space, just for you.</h2><p>Keep track of your orders, save your favorites and make your next visit easier.</p><div class="stats-grid"><article><small>Your orders</small><strong><?=query('SELECT COUNT(*) FROM orders WHERE user_id=?',[$u['id']])->fetchColumn()?></strong><a href="/account/orders">View orders ↗</a></article><article><small>Saved addresses</small><strong><?=query('SELECT COUNT(*) FROM user_addresses WHERE user_id=?',[$u['id']])->fetchColumn()?></strong><a href="/account/addresses">Manage addresses ↗</a></article></div>
<?php elseif($section==='orders'): $orders=query('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 100',[$u['id']])->fetchAll(); ?><h2>My orders</h2><?php if(!$orders): ?><p>You haven’t placed an order yet. <a href="/shop">Explore WIKI ↗</a></p><?php endif ?><?php foreach($orders as $o): ?><a class="order-row" href="/order/<?=e($o['number'])?>"><strong><?=e($o['number'])?></strong><span><?=e(substr($o['created_at'],0,10))?></span><span><?=money($o['total'])?></span><span class="badge"><?=e($o['status'])?></span><span><?=e($o['payment_status'])?> ↗</span></a><?php endforeach ?>
<?php elseif($section==='profile'): ?><h2>Your details</h2><form class="form-panel" method="post" action="/api/action" data-ajax><?=csrf_field()?><input type="hidden" name="action" value="profile"><label>Name<input name="name" value="<?=e($u['name'])?>" required maxlength="120"></label><label>Email<input type="email" value="<?=e($u['email'])?>" disabled></label><label>Phone<input name="phone" value="<?=e($u['phone'])?>" maxlength="30"></label><button class="btn">Save details</button></form><form class="form-panel" method="post" action="/account/profile"><?=csrf_field()?><input type="hidden" name="action" value="password"><h2>Change password</h2><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New password<input name="password" type="password" minlength="12" maxlength="200" autocomplete="new-password" required></label><button class="btn">Update password</button></form>
<?php elseif($section==='addresses'): ?><h2>Your addresses</h2><div class="two-grid"><?php foreach(query('SELECT * FROM user_addresses WHERE user_id=?',[$u['id']])->fetchAll() as $a): ?><article class="panel"><h3><?=e($a['label'])?></h3><a class="underlined" href="/account/addresses?edit=<?=e($a['id'])?>">Edit address</a><p><?=e($a['address'])?><br><?=e($a['city'].', '.$a['province'].' '.$a['postal_code'])?><br><?=e($a['country'])?></p><form method="post" action="/api/action" data-ajax data-reload data-confirm="Remove this saved address?"><?=csrf_field()?><input type="hidden" name="action" value="delete-address"><input type="hidden" name="id" value="<?=e($a['id'])?>"><button class="text-button">Remove</button></form></article><?php endforeach ?></div><?php require ROOT.'/views/partials/address-editor.php'; ?>
<?php elseif($section==='wishlist'): ?><h2>Your favorites, all together.</h2><div class="product-grid compact-grid"><?php $saved=query("SELECT p.*,(SELECT path FROM product_images WHERE product_id=p.id ORDER BY position,id LIMIT 1) image,NULL rating FROM products p JOIN wishlist_items wi ON wi.product_id=p.id JOIN wishlists w ON w.id=wi.wishlist_id WHERE w.user_id=? AND p.status='active'",[$u['id']])->fetchAll(); foreach($saved as $item) require ROOT.'/views/partials/card.php'; ?></div><?php if(!$saved): ?><p>Save the pieces you love by tapping the heart on any product.</p><a class="btn" href="/shop">Find your favorites</a><?php endif ?>
<?php elseif($section==='returns'): ?><h2>Returns & refunds</h2><p>Open a delivered order to request a return within 14 days.</p><?php foreach(query('SELECT r.*,o.number FROM returns r JOIN orders o ON o.id=r.order_id WHERE o.user_id=? ORDER BY r.id DESC',[$u['id']])->fetchAll() as $r): ?><article class="panel"><a href="/order/<?=e($r['number'])?>"><?=e($r['number'])?> ↗</a><p><?=e($r['reason'])?></p><span class="badge"><?=e($r['status'])?></span></article><?php endforeach ?><?php endif ?></div></div></section>
